<?php require_once 'config/app.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(strlen($pass)<8)$error='Password must be at least 8 characters.';else{try{$hash=password_hash($pass,PASSWORD_DEFAULT);stmt($conn,'INSERT INTO users(full_name,email,password,role) VALUES(?,?,?,\'customer\')','sss',[$name,$email,$hash]);redirect('login.php?registered=1');}catch(mysqli_sql_exception $e){$error=$e->getCode()===1062?'This email is already registered.':'Registration failed. Please try again.';}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account | AutoCare</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><div class="auth-side"><div class="auth-brand">Auto<span>Care</span></div><h1>Your car.<br>Our priority.</h1><p>Create an account to register your vehicles, request service appointments and follow your service history.</p></div><div class="auth-box"><form class="auth-card" method="post"><h2>Create your account</h2><p>Join AutoCare and manage your vehicle care.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="field"><label>Full name</label><input name="full_name" required maxlength="120"></div><div class="field"><label>Email address</label><input type="email" name="email" required></div><div class="field"><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required></div><button class="btn">Create account</button><div class="auth-bottom">Already registered? <a href="login.php">Sign in</a></div></form></div></body></html>
